import * as React from "react"
import { Link, navigate } from "gatsby"
import Header from "../components/Header"
import Seo from "../components/Seo"
import { ArrowRight } from "../components/Icons"
import { supabase, configured } from "../lib/supabase"
import { useAuth } from "../context/auth"
import { AFFILIATE_MESSAGES, affiliateFor } from "../lib/affiliate"
import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"
import * as s from "../components/admin/Admin.module.css"

/**
 * What your adverts did — MTC-FCS-041.
 * ============================================================================
 * The third part of Nate's system: "they will be able to login and track which
 * ads worked and which groups worked, etc."
 *
 * ── IDENTITY IS THE ACCOUNT THEY ALREADY HAVE ──────────────────────────────
 * The signed-in email is the affiliate key, so there is no second login to
 * build, no second password to lose, and the report cannot be pointed at
 * somebody else's numbers by editing a URL — there is no id in the URL at all.
 * When the Google Form list arrives it maps a person to this email; nothing
 * here changes.
 *
 * ── TWO TABLES, BECAUSE THEY ANSWER DIFFERENT QUESTIONS ────────────────────
 * By CODE says which image and which wording worked. By GROUP says where to
 * post next. A marketer who only sees one of them keeps making the same
 * decision with half the information.
 */

const Stat = ({ label, value, note }) => (
  <div className={s.cell}>
    <span className={s.cellName}>{label}</span>
    <span className={s.cellState}>{value}</span>
    {note ? <span className={s.cellName}>{note}</span> : null}
  </div>
)

const when = value => (value ? new Date(value).toLocaleDateString() : "—")

const AffiliatePage = () => {
  const { user, ready } = useAuth()
  const [report, setReport] = React.useState(null)
  const [error, setError] = React.useState("")
  const [busy, setBusy] = React.useState(false)

  const load = React.useCallback(async () => {
    const client = supabase()
    if (!client) return
    setBusy(true)
    setError("")
    try {
      const { data } = await client.auth.getSession()
      const token = data?.session?.access_token
      /* An Edge Function, not /api — FCS-067. The Gatsby route does not
         exist on a static host, so this answered 404 for everybody and the
         dashboard showed a red error to affiliates whose only problem was
         having posted nothing yet. */
      const res = await fetch(apiUrl("affiliate-report"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          apikey: SUPABASE_PUBLISHABLE_KEY,
          Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
        },
        body: "{}",
      })
      const body = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(body.message || `Could not load the report (HTTP ${res.status}).`)
        return
      }
      /* An empty report is a normal answer, not a failure: zeroes and a line
         saying what to do next, never a red box. */
      setReport(body)
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy(false)
    }
  }, [])

  /* ── AN AFFILIATE IS NOT A CONTRACTOR — MTC-FCS-037..041 ──────────────
     Being signed in was the whole check here, which meant every contractor
     who logged in landed in the marketing dashboard. Marketers are a
     separate, approved list; a website customer asking for this page is told
     plainly that it is not their side of the product rather than being shown
     an empty report. */
  const [role, setRole] = React.useState({ status: "checking", affiliate: null })

  React.useEffect(() => {
    if (!ready) return
    if (!user) {
      setRole({ status: "anonymous", affiliate: null })
      return
    }
    affiliateFor(user).then(setRole)
  }, [ready, user])

  React.useEffect(() => {
    if (ready && user && role.status === "active") load()
  }, [ready, user, role.status, load])

  if (!configured()) {
    return (
      <>
        <Header />
        <main className={s.page}>
          <div className="container">
            <h1 className={s.title}>Your adverts</h1>
            <p className={s.lead}>Accounts are not set up on this environment.</p>
          </div>
        </main>
      </>
    )
  }

  /* Everything that is not an approved affiliate ends here, each with its
     own sentence — see AFFILIATE_MESSAGES for why "we could not check" is
     never allowed to read as "you are not one". */
  if (ready && user && role.status !== "active" && role.status !== "checking") {
    const message = AFFILIATE_MESSAGES[role.status] || AFFILIATE_MESSAGES.unknown
    return (
      <>
        <Header />
        <main className={s.page}>
          <div className="container">
            <h1 className={s.title}>{message.title}</h1>
            <p className={s.lead}>{message.body}</p>
          </div>
        </main>
      </>
    )
  }

  /* ── NOTHING UNTIL WE KNOW WHO THIS IS ────────────────────────────────
     Every guard below waits on `ready`, so before the session has loaded
     none of them fired and the dashboard rendered underneath — a stranger
     opening this page saw a marketing report reading 0 visits, 0 sales, 0
     codes for a fraction of a second before being asked to log in. Those
     zeroes are not their numbers and not anybody's; they are the component's
     initial state, and showing them reads as "your adverts did nothing". */
  if (!ready || role.status === "checking") {
    return (
      <>
        <Header />
        <main className={s.page}>
          <div className="container">
            <h1 className={s.title}>Your adverts</h1>
            <p className={s.lead}>Loading…</p>
          </div>
        </main>
      </>
    )
  }

  if (ready && !user) {
    return (
      <>
        <Header />
        <main className={s.page}>
          <div className="container">
            <h1 className={s.title}>Your adverts</h1>
            <p className={s.lead}>
              Log in to see which of your images brought people in, and which groups they came
              from. It is the same account you use everywhere else here.
            </p>
            <button
              type="button"
              className={s.button}
              onClick={() => navigate("/log-in?next=/affiliate")}
            >
              Log in
            </button>
          </div>
        </main>
      </>
    )
  }

  const totals = report?.totals || { visits: 0, sales: 0, rate: 0 }

  return (
    <>
      <Header />
      <main className={s.page}>
        <div className="container">
          <div className={s.head}>
            <h1 className={s.title}>Your adverts</h1>
            <Link to="/ad-studio" className={s.button}>
              Make another
              <ArrowRight className="btn__arrow" />
            </Link>
          </div>
          <p className={s.lead}>
            One row per code you have posted. A code with visits and no sales means the image
            worked and the page did not — that is worth knowing separately.
          </p>

          <div className={s.board}>
            <Stat label="Visits" value={totals.visits} note="people who scanned or clicked" />
            <Stat label="Sales" value={totals.sales} note="they went on to buy" />
            <Stat label="Conversion" value={`${totals.rate}%`} note="across every code" />
            <Stat label="Codes" value={report?.codes?.length ?? 0} note="you have made" />
          </div>

          {error ? <p className={s.error}>{error}</p> : null}

          <div className={s.card}>
            <div className={s.head}>
              <h2 className={s.cardTitle}>Which adverts worked</h2>
              <button type="button" className={`${s.button} ${s.ghost}`} onClick={load} disabled={busy}>
                {busy ? "Loading…" : "Refresh"}
              </button>
            </div>

            {!report ? (
              <p className={s.note}>Loading…</p>
            ) : report.codes.length === 0 ? (
              <p className={s.note}>
                {report.message || "Nothing yet."} Codes only count once they are saved while you
                are logged in.
              </p>
            ) : (
              <div className={s.scroll}>
                <table className={s.table}>
                  <thead>
                    <tr>
                      <th>Code</th>
                      <th>Posted in</th>
                      <th>Advert</th>
                      <th>Visits</th>
                      <th>Sales</th>
                      <th>Rate</th>
                      <th>Came from</th>
                      <th>Last activity</th>
                    </tr>
                  </thead>
                  <tbody>
                    {report.codes.map(row => (
                      <tr key={row.code}>
                        <td className={s.mono}>{row.code}</td>
                        <td>{row.placedIn || "—"}</td>
                        <td>
                          {row.template || "—"}
                          {row.trade ? ` · ${row.trade}` : ""}
                        </td>
                        <td>{row.visits}</td>
                        <td>
                          <span className={row.sales > 0 ? `${s.pill} ${s.pillGood}` : s.pill}>
                            {row.sales}
                          </span>
                        </td>
                        <td>{row.rate}%</td>
                        <td>{row.sources.map(x => `${x.name} (${x.count})`).join(", ") || "—"}</td>
                        <td>{when(row.lastSeen)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          <div className={s.card}>
            <h2 className={s.cardTitle}>Which groups worked</h2>
            {!report?.groups?.length ? (
              <p className={s.note}>Nothing to compare yet.</p>
            ) : (
              <div className={s.scroll}>
                <table className={s.table}>
                  <thead>
                    <tr>
                      <th>Group</th>
                      <th>Codes posted</th>
                      <th>Visits</th>
                      <th>Sales</th>
                    </tr>
                  </thead>
                  <tbody>
                    {report.groups.map(row => (
                      <tr key={row.group}>
                        <td>{row.group}</td>
                        <td>{row.codes}</td>
                        <td>{row.visits}</td>
                        <td>{row.sales}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            <p className={s.note}>
              A visit is counted once per person, not once per page they look at. Sales are counted
              when the payment actually goes through.
            </p>
          </div>
        </div>
      </main>
    </>
  )
}

export const Head = () => (
  <Seo title="Your adverts" description="Which of your adverts and groups brought people in." noindex />
)

export default AffiliatePage
